class Solution
{
    public int MinTriangleSum(List<List<int>> triangle)
    {
        // Raj Thomas 29th Jul 2026 11:15PM IST 
        int len = triangle.Count;
        int row = 0, col = 0;
        int[][] dp = new int[len][];
        for(int i = 0; i < len; i++) {
            dp[i] = new int[i + 1];
            Array.Fill(dp[i], int.MaxValue);
        }

        int mini = Find(triangle, len, row, col, dp);
        return mini;

    }

    private int Find(List<List<int>> triangle, int len, int row, int col, int[][] dp) {

        if(row == len - 1) return triangle[row][col];

        if(dp[row][col] != int.MaxValue) return dp[row][col];

        int down = triangle[row][col] + Find(triangle, len, row + 1, col, dp);
        int diagonal = triangle[row][col] + Find(triangle, len, row + 1, col + 1, dp);

        int mini = Math.Min(down, diagonal);
        dp[row][col] = mini;

        return dp[row][col];

    }
}
